{"command":"python3 -c "
import csv
with open('outputs/t01_selected_indicators.csv', 'r') as f:
    reader = csv.reader(f)
    next(reader)
    valid_directions = {'higher_is_better', 'lower_is_better', 'contextual'}
    for row in reader:
        direction = row[4]
        if direction not in valid_directions:
            print(f'Invalid direction: {direction}')
